// Concatenates supabase/migrations into one transactional script for the
// Supabase SQL editor: supabase/install-uniattend.sql
//   node scripts/bundle-sql.mjs
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "supabase", "migrations");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const out = [
  "-- UniAttend install script. Generated by scripts/bundle-sql.mjs — do not edit by hand.",
  "-- Paste into Supabase → SQL Editor and run once. It is one transaction: if any",
  "-- statement fails, nothing is changed. It only creates the `uniattend` schema",
  "-- (plus one trigger on auth.users) and never touches tables in `public`.",
  "begin;",
  "do $$ begin",
  "  if exists (select 1 from pg_tables where schemaname = 'uniattend') then",
  "    raise exception 'UniAttend is already installed in this project (schema uniattend has tables).';",
  "  end if;",
  "end $$;",
  ...files.map((f) => `\n-- ===================================================== ${f}\n${readFileSync(join(dir, f), "utf8")}`),
  "commit;",
  "",
].join("\n");

writeFileSync(join(dir, "..", "install-uniattend.sql"), out);
console.log(`wrote supabase/install-uniattend.sql from ${files.length} migrations (${out.length} bytes)`);
